  class DraggableFrame {
    $instance;
    instance;
    dragging;
    startX;
    startY;
    offsetX;
    offsetY;
    constructor(node) {
      this.$instance = $(node);
      this.instance = node.get(0);
      this.dragging = false;
      this.startX = this.startY = this.offsetX = this.offsetY = 0;
      this.$instance.addClass("mcmodder-draggable");
      this.instance.addEventListener("pointerdown", (ev) => this.onPointerdown(ev));
      this.instance.addEventListener("pointermove", (ev) => this.onPointermove(ev));
      this.instance.addEventListener("pointerup", (ev) => this.onPointerup(ev));
      this.instance.addEventListener("pointercancel", (ev) => this.onPointerup(ev));
    }
    onPointerdown(e2) {
      this.dragging = true;
      this.startX = e2.clientX;
      this.startY = e2.clientY;
      this.offsetX = e2.offsetX;
      this.offsetY = e2.offsetY;
      if (!this.instance.hasPointerCapture(e2.pointerId)) {
        this.instance.setPointerCapture(e2.pointerId);
      }
    }
    onPointermove(e2) {
      if (!this.dragging) return;
      this.$instance.css({
        left: this.startX - this.offsetX + (e2.clientX - this.startX) + "px",
        top: this.startY - this.offsetY + (e2.clientY - this.startY) + "px"
      });
    }
    onPointerup(e2) {
      this.dragging = false;
      if (this.instance.hasPointerCapture(e2.pointerId)) {
        this.instance.releasePointerCapture(e2.pointerId);
      }
    }
  }
